UPDATE clients SET taxOffice=CASE WHEN replace(replace(replace(replace(trim(taxOffice),' ',''),char(9),''),char(10),''),char(160),'') IN ('تالتورابع','تالتواربع','ثالثورابع','ثالث','تالت') THEN 'تالت و رابع' WHEN replace(replace(replace(replace(trim(taxOffice),' ',''),char(9),''),char(10),''),char(160),'') IN ('ثان','تان','مهنحرهثان','مهنحرةثان') THEN 'مهن حره ثان' ELSE taxOffice END WHERE taxOffice<>CASE WHEN replace(replace(replace(replace(trim(taxOffice),' ',''),char(9),''),char(10),''),char(160),'') IN ('تالتورابع','تالتواربع','ثالثورابع','ثالث','تالت') THEN 'تالت و رابع' WHEN replace(replace(replace(replace(trim(taxOffice),' ',''),char(9),''),char(10),''),char(160),'') IN ('ثان','تان','مهنحرهثان','مهنحرةثان') THEN 'مهن حره ثان' ELSE taxOffice END;
