UPDATE inspectionCases SET data=json_set(data,'$.office',CASE WHEN replace(replace(replace(replace(trim(json_extract(data,'$.office')),' ',''),char(9),''),char(10),''),char(160),'') IN ('تالتورابع','تالتواربع','ثالثورابع','ثالث','تالت') THEN 'تالت و رابع' WHEN replace(replace(replace(replace(trim(json_extract(data,'$.office')),' ',''),char(9),''),char(10),''),char(160),'') IN ('ثان','تان','مهنحرهثان','مهنحرةثان') THEN 'مهن حره ثان' ELSE json_extract(data,'$.office') END),revision=revision+1,updated=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE json_extract(data,'$.office')<>CASE WHEN replace(replace(replace(replace(trim(json_extract(data,'$.office')),' ',''),char(9),''),char(10),''),char(160),'') IN ('تالتورابع','تالتواربع','ثالثورابع','ثالث','تالت') THEN 'تالت و رابع' WHEN replace(replace(replace(replace(trim(json_extract(data,'$.office')),' ',''),char(9),''),char(10),''),char(160),'') IN ('ثان','تان','مهنحرهثان','مهنحرةثان') THEN 'مهن حره ثان' ELSE json_extract(data,'$.office') END;
