INSERT INTO inspectionHistory (id,caseId,revision,data,actor,created) SELECT id||'-office-names-'||revision,id,revision,data,'توحيد مسميات المأموريات بطلب صاحب المكتب',updated FROM inspectionCases c WHERE NOT EXISTS(SELECT 1 FROM inspectionHistory h WHERE h.caseId=c.id AND h.revision=c.revision);
